// Plain-language glossary.
const glossary = [
  ["Last frost date", "last-frost", "The date after which freezing nights usually stop in spring. Rainline Garden uses the typical (median) date: in half of years the last frost comes later, so tender crops wait longer."],
  ["First frost date", "first-frost", "The date the first fall freeze usually arrives. Warm-season crops die at the first frost; cool-season crops keep going."],
  ["Frost-free season", "frost-free-season", "The number of days between the last spring frost and the first fall frost. It's your growing season for tomatoes, squash and other tender crops."],
  ["Sow seeds (direct sow)", "direct-sow", "Planting seeds straight into the garden soil where they'll grow, instead of starting them in pots."],
  ["Starts (transplants)", "starts", "Young plants grown in small pots, either by you indoors or bought at a nursery, then planted in the garden."],
  ["Start seeds indoors", "start-indoors", "Sowing seeds in trays inside, under lights or in a sunny window, weeks before it's warm enough outside. It gives slow crops like tomatoes and peppers a head start."],
  ["Hardening off", "hardening-off", "Getting indoor seedlings used to sun, wind and cool nights by setting them outside for a few hours a day, longer each day, for about a week before planting."],
  ["Cool-season crop", "cool-season", "A crop that grows best in cool weather and handles light frost, like peas, lettuce, kale and carrots. Plant these in early spring and again for fall."],
  ["Warm-season crop", "warm-season", "A crop that's killed by frost and needs warm soil, like tomatoes, beans, squash and basil. Plant these after the last frost once the soil warms."],
  ["Soil temperature", "soil-temperature", "How warm the soil is a few inches down. In the Northwest it lags weeks behind the air, which is why warm crops wait. A soil thermometer costs about $10."],
  ["Bolting", "bolting", "When a leafy crop like spinach or lettuce suddenly sends up a flower stalk, usually in heat or long days. The leaves turn bitter, so harvest before it happens."],
  ["Thinning", "thinning", "Pulling out extra seedlings so the rest have room to grow. Carrots, beets and radishes need it."],
  ["Succession planting", "succession", "Sowing a short row every two or three weeks instead of all at once, so you get a steady harvest."],
  ["Row cover", "row-cover", "A light fabric laid over plants. It traps warmth, guards against light frost and keeps insects off."],
  ["Wall-o-water and cloches", "cloche", "Covers that sit over a single plant to keep it warm. A wall-o-water is a ring of water-filled tubes that soaks up heat by day and releases it at night."],
  ["Mulch", "mulch", "A layer of straw, leaves, compost or plastic on top of the soil. It holds moisture, smothers weeds and, if dark plastic, warms the soil."],
  ["Days to harvest", "days-to-harvest", "Roughly how long from planting outdoors until the first harvest. Seed packets list it; it's longer in cool summers."],
  ["Onion sets", "onion-sets", "Small dormant onion bulbs you plant instead of seeds. They're the easiest way to grow onions."],
  ["Seed potatoes", "seed-potatoes", "Potatoes grown to be planted, certified free of disease. Grocery-store potatoes are often treated to stop sprouting."],
  ["Curing", "curing", "Drying a harvest so it stores well: winter squash in a warm room, onions and garlic in a shady, airy spot."],
  ["Cover crop", "cover-crop", "A crop like crimson clover or cereal rye sown in empty beds over winter to protect and feed the soil."],
  ["Hardneck and softneck garlic", "hardneck-softneck", "Hardneck garlic has a stiff center stalk, bigger cloves and better cold tolerance. Softneck stores longer and can be braided."],
  ["Rain shadow", "rain-shadow", "The dry area on the downwind side of a mountain range. Storms drop their rain on the west slopes of the Cascades, so the east side gets far less."],
  ["Microclimate", "microclimate", "A spot that's warmer, colder, wetter or drier than the town around it, like the bed against a south-facing wall or a low, shady corner."],
  ["Frost pocket", "frost-pocket", "A low spot where cold air settles on still nights, so frost hits there first in fall and lingers longest in spring."],
  ["Hardiness zone", "hardiness-zone", "A USDA number based on how cold your winters get. It tells you which perennials, shrubs and trees will survive, not when to plant vegetables."],
  ["Compost", "compost", "Rotted plant scraps, leaves and manure. Mixed into soil, it feeds plants, loosens clay and helps sandy soil hold water."],
  ["Soil pH", "soil-ph", "How acidic or alkaline the soil is, on a scale where 7 is neutral. Most vegetables like it slightly acidic (about 6 to 7); blueberries like it much more acidic."],
  ["Lime", "lime", "Ground limestone added to make acidic soil less acidic. Rainy west-side soils often need it; a soil test tells you how much."],
  ["Raised bed", "raised-bed", "A garden bed built up above the ground, often inside a wood frame. It drains and warms faster in wet Northwest springs."],
  ["Heirloom", "heirloom", "An old variety passed down for generations. If you save its seeds, you get the same plant next year."],
  ["Hybrid (F1)", "hybrid", "A variety made by crossing two different parents. Hybrids are often vigorous or disease resistant, but seeds saved from them won't grow true."],
  ["Open-pollinated", "open-pollinated", "Seeds made by natural pollination that grow into plants like the parent. All heirlooms are open-pollinated."],
  ["Determinate and indeterminate", "determinate", "Determinate (bush) tomatoes grow to a set size and ripen most of their fruit at once. Indeterminate (vining) tomatoes keep growing and fruiting until frost and need tall stakes."],
  ["Pollination", "pollination", "Moving pollen between flowers so they can turn into fruit. Bees do most of it; squash, berries and fruit trees all depend on it."],
  ["Fruit set", "fruit-set", "When a pollinated flower starts to swell into a fruit. Cold nights below about 55\u00b0F can stop tomatoes and peppers setting fruit."],
  ["Side-dressing", "side-dressing", "Adding fertilizer or compost along a row or around plants partway through the season, when hungry crops start to need more."],
  ["Pinching", "pinching", "Nipping off the tip of a shoot to make a plant bushier, as with basil, or removing the side shoots (suckers) on vining tomatoes."],
  ["Staking and trellising", "trellis", "Supports that hold plants up off the ground: stakes or cages for tomatoes, a trellis or netting for peas, pole beans and cucumbers."],
  ["Overwintering", "overwintering", "Keeping a crop in the ground through winter, like garlic, kale, leeks or fava beans, for an early harvest the next year."],
  ["Bare-root", "bare-root", "Plants sold while dormant with no soil around the roots, like fruit trees, berries and asparagus in late winter. They're cheaper and settle in fast."],
  ["Dormant", "dormant", "Resting for winter, with no leaves or new growth. It's the best time to plant or prune many fruit trees and shrubs."],
  ["Crown", "crown", "The spot where a plant's stems meet its roots. Planting the crown too deep can rot strawberries, rhubarb and asparagus."],
  ["Cane", "cane", "A long, woody stem on raspberries and blackberries. Most varieties fruit on canes in their second year, then those canes are cut out."],
  ["Runner", "runner", "A stem a strawberry plant sends along the ground that roots into a new plant. Pinch them off for bigger berries, or let them fill a bed."],
  ["Garlic scape", "garlic-scape", "The curly flower stalk on hardneck garlic. Cut it off in early summer so the bulb grows bigger; it's good to eat."],
  ["Late blight", "late-blight", "A disease that turns tomato and potato leaves and fruit brown and mushy fast, usually once fall rains start. Keep leaves dry and pick early."],
  ["Clubroot", "clubroot", "A soil disease that swells and twists the roots of cabbage-family crops. Raising soil pH with lime and rotating crops help keep it away."],
  ["Damping off", "damping-off", "When seedlings suddenly flop over at the soil line, caused by fungi in cold, wet soil. Use clean pots, fresh seed-starting mix and good airflow."],
  ["Blossom end rot", "blossom-end-rot", "A dark, sunken patch on the bottom of tomatoes and peppers. It's linked to uneven watering, so water deeply and regularly and mulch."],
  ["Drip irrigation and soaker hose", "drip-irrigation", "Hoses that leak water slowly right at the roots. They save water in dry summers and keep leaves dry, which helps prevent disease."],
  ["Drip line", "drip-line", "The edge of a tree's canopy, where rain drips off the outer leaves. Most of a tree's feeding roots spread out to here and beyond."],
  ["Cold frame", "cold-frame", "A bottomless box with a clear lid that works like a small greenhouse, for early spring starts and late fall greens."],
  ["Cut-and-come-again", "cut-and-come-again", "Picking the outer leaves and leaving the center to keep growing, so one planting of lettuce, chard or kale feeds you for weeks."],
  ["Inoculant", "inoculant", "A powder of helpful bacteria you coat pea and bean seeds with. The bacteria help the plants pull nitrogen from the air."],
  ["Grafting and rootstock", "rootstock", "Most fruit trees are two plants joined together: the top (the variety) gives the fruit, and the rootstock below sets how big the tree grows."]
];

module.exports = { crops, beginner, beginnerWhy, glossary };
